import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), canvas=$('#view');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#111920'); scene.fog=new THREE.FogExp2('#111920',.022);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.1,180); camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.22;
scene.add(new THREE.HemisphereLight(0x9dbab4,0x211c23,2.1));
const key=new THREE.DirectionalLight(0xe4d2a7,2.3); key.position.set(-7,12,4); key.castShadow=true; key.shadow.mapSize.set(1024,1024); scene.add(key);
const tealLight=new THREE.PointLight(0x34c7b1,25,26,2); tealLight.position.set(0,5,0); scene.add(tealLight);
const violetLight=new THREE.PointLight(0x7853b5,22,22,2); violetLight.position.set(0,4,-21); scene.add(violetLight);
const goldLight=new THREE.PointLight(0xd7a64e,16,19,2); goldLight.position.set(-18,3,-7); scene.add(goldLight);
const mat=(color,rough=.75,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const floorMat=mat('#202d2d',.87), stoneMat=mat('#303a3b',.92), darkStone=mat('#161e23',.95), goldMat=mat('#c5a45c',.48,.65), tealMat=mat('#176c67',.42,.25);
// Sanctum floor, inlaid wards, and cathedral architecture.
const floor=new THREE.Mesh(new THREE.CircleGeometry(43,96),floorMat); floor.rotation.x=-Math.PI/2; floor.position.y=-.13; floor.receiveShadow=true; scene.add(floor);
const arenaRing=new THREE.Mesh(new THREE.RingGeometry(8.7,9,96),new THREE.MeshBasicMaterial({color:0xb39352,side:THREE.DoubleSide,transparent:true,opacity:.48})); arenaRing.rotation.x=-Math.PI/2; arenaRing.position.y=-.105; scene.add(arenaRing);
for(let r of [3,6,9,13,18,26]){const ring=new THREE.Mesh(new THREE.RingGeometry(r-.012,r+.012,96),new THREE.MeshBasicMaterial({color:r===9?0xa38a4a:0x718580,side:THREE.DoubleSide,transparent:true,opacity:r===9?.3:.12}));ring.rotation.x=-Math.PI/2;ring.position.y=-.11;scene.add(ring)}
for(let i=0;i<16;i++){const a=i*Math.PI/8;const ob=new THREE.Mesh(new THREE.BoxGeometry(.09,.035,3.8),new THREE.MeshBasicMaterial({color:i%2?0x398b81:0xb59146,transparent:true,opacity:.4}));ob.position.set(Math.sin(a)*6.8,-.095,Math.cos(a)*6.8);ob.rotation.y=a;scene.add(ob)}
const arenaWall=new THREE.Mesh(new THREE.CylinderGeometry(33,34,11,48,1,true),new THREE.MeshStandardMaterial({color:0x202c31,roughness:.92,side:THREE.BackSide}));arenaWall.position.y=5.1;scene.add(arenaWall);
const pillars=[];for(let i=0;i<16;i++){let a=i*Math.PI/8,x=Math.sin(a)*23,z=Math.cos(a)*23;const g=new THREE.Group();g.position.set(x,0,z);const base=new THREE.Mesh(new THREE.CylinderGeometry(1.05,1.3,1.0,8),darkStone);base.position.y=.5;g.add(base);const shaft=new THREE.Mesh(new THREE.CylinderGeometry(.72,.92,9.3,8),stoneMat);shaft.position.y=5.3;shaft.castShadow=true;g.add(shaft);const cap=new THREE.Mesh(new THREE.CylinderGeometry(1.15,.85,.85,8),goldMat);cap.position.y=10.35;g.add(cap);const flame=new THREE.Mesh(new THREE.OctahedronGeometry(.23),new THREE.MeshBasicMaterial({color:i%2?0x42d5c1:0xd9a94f}));flame.position.y=9.6;g.add(flame);const lamp=new THREE.PointLight(i%2?0x2aaca0:0xc98638,8,11,2);lamp.position.set(0,9.6,0);g.add(lamp);scene.add(g);pillars.push(g)}
for(let i=0;i<8;i++){const a=i*Math.PI/4;const p=new THREE.Mesh(new THREE.BoxGeometry(4,8,.55),darkStone);p.position.set(Math.sin(a)*33,3.8,Math.cos(a)*33);p.lookAt(0,3.8,0);scene.add(p)}
// Player state and controls
const player={pos:new THREE.Vector3(0,1.65,7),vel:new THREE.Vector3(),yaw:0,pitch:0,hp:100,maxHp:100,mana:100,maxMana:100,ground:true,crouch:false,sprint:false,locked:null,kills:0,wave:0,active:false,paused:true,casting:0,invuln:0};
const keys={};let mouseLocked=false,runClock=0,lastShot=0,lastDamage=0,toastTimer=0,shotCount=0;
camera.position.copy(player.pos); scene.add(camera);
const spellBook=[
 {id:'bolt',name:'Arcane Bolt',icon:'✧',sub:'QUICK · PRECISE',cost:6,damage:24,range:42,cool:.24,desc:'Fast, accurate bolts of focused arcana.'},
 {id:'fire',name:'Fireball',icon:'☄',sub:'EXPLOSIVE · AREA',cost:16,damage:40,range:33,cool:.75,desc:'Detonates on impact, scorching nearby foes.'},
 {id:'void',name:'Void Lance',icon:'⟡',sub:'PIERCING · HEAVY',cost:22,damage:62,range:48,cool:1.05,desc:'A charged lance that pierces all in its path.'},
 {id:'storm',name:'Lightning Storm',icon:'ϟ',sub:'CHAIN · MULTI-TARGET',cost:25,damage:31,range:30,cool:1.3,desc:'Chains lightning through up to four enemies.'},
 {id:'barrage',name:'Arcane Barrage',icon:'⁂',sub:'RAPID · VOLLEY',cost:20,damage:13,range:33,cool:.9,desc:'Six seeking shards in a quick volley.'},
 {id:'bind',name:'Binding Magic',icon:'⌘',sub:'CONTROL · SLOW',cost:14,damage:10,range:29,cool:.8,desc:'Roots a target in a shimmering snare.'},
 {id:'ruin',name:'Destruction',icon:'✹',sub:'ULTIMATE · DEVASTATING',cost:48,damage:78,range:23,cool:3.2,desc:'A devastating close-range arcane nova.'}
];
let loadout=['bolt','fire','void','storm'],spellIndex=0, cooldowns={}; const getSelected=()=>spellBook.filter(s=>loadout.includes(s.id));
function buildLoadout(){const grid=$('#loadoutGrid');grid.innerHTML='';spellBook.forEach(s=>{const el=document.createElement('button');el.className='spell-card'+(loadout.includes(s.id)?' selected':'');el.innerHTML=`<div class="spell-icon">${s.icon}</div><div><b>${s.name}</b><small>${s.desc}<br>${s.cost} ARC · ${s.damage} DMG</small></div><span class="spell-check">${loadout.includes(s.id)?'✦':''}</span>`;el.onclick=()=>{if(loadout.includes(s.id)){if(loadout.length<=1)return;loadout=loadout.filter(x=>x!==s.id)}else if(loadout.length<4)loadout.push(s.id);spellIndex=Math.min(spellIndex,loadout.length-1);buildLoadout()};grid.append(el)});$('#selectedCount').textContent=`${loadout.length} / 4 SELECTED`;}
function renderSpellHud(){let s=getSelected()[spellIndex];if(!s)return;$('#spellName').textContent=s.name.toUpperCase();$('#spellSub').textContent=s.sub;$('#spellIcon').textContent=s.icon;$('#spellSlots').innerHTML=getSelected().map((_,i)=>`<span class="spell-slot ${i===spellIndex?'active':''}"></span>`).join('')}
buildLoadout();renderSpellHud();
const title=$('#titleScreen'),loadoutScreen=$('#loadout'),pauseScreen=$('#pauseScreen');
$('#beginBtn').onclick=()=>{title.classList.add('hidden');loadoutScreen.classList.remove('hidden')};
$('#closeLoadout').onclick=()=>{loadoutScreen.classList.add('hidden');title.classList.remove('hidden')};
$('#deployBtn').onclick=()=>{loadoutScreen.classList.add('hidden');startRun()};
$('#loadoutBtn').onclick=()=>{pauseScreen.classList.add('hidden');buildLoadout();loadoutScreen.classList.remove('hidden');player.paused=true;document.exitPointerLock?.()};
$('#resumeBtn').onclick=()=>resume();$('#pauseBtn').onclick=()=>pause();$('#againBtn').onclick=()=>{$('#victoryScreen').classList.add('hidden');startRun()};
function sfx(freq=350,dur=.1,type='sine',vol=.035){try{const ac=sfx.ac||(sfx.ac=new AudioContext()),o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(freq,ac.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(38,freq*.47),ac.currentTime+dur);g.gain.setValueAtTime(vol,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+dur);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+dur)}catch{}}
function announce(text,sub=''){let el=$('#waveAnnounce');el.innerHTML=`<span>THE SANCTUM STIRS</span><b>${text}</b><i>${sub}</i>`;el.classList.remove('hidden');el.style.animation='none';void el.offsetWidth;el.style.animation='';setTimeout(()=>el.classList.add('hidden'),3200)}
function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
function startRun(){player.hp=100;player.mana=100;player.kills=0;player.wave=0;player.pos.set(0,1.65,7);player.vel.set(0,0,0);player.yaw=0;player.pitch=0;player.active=true;player.paused=false;player.locked=null;cooldowns={};enemies.forEach(e=>scene.remove(e.group));enemies.length=0;projectiles.forEach(p=>scene.remove(p.mesh));projectiles.length=0;$('#hud').classList.remove('hidden');$('#victoryScreen').classList.add('hidden');$('#killCount').textContent='00';updateHud();nextWave();requestLock()}
function requestLock(){canvas.requestPointerLock?.()}
function pause(){if(!player.active)return;player.paused=true;pauseScreen.classList.remove('hidden');document.exitPointerLock?.()}
function resume(){pauseScreen.classList.add('hidden');player.paused=false;requestLock()}
document.addEventListener('pointerlockchange',()=>{mouseLocked=document.pointerLockElement===canvas;$('#crosshairHint').classList.toggle('hidden',!player.active||player.paused||mouseLocked);if(player.active&&!player.paused&&!mouseLocked){} });
document.addEventListener('mousemove',e=>{if(!mouseLocked||!player.active||player.paused)return;player.yaw-=e.movementX*.0022;player.pitch-=e.movementY*.0019;player.pitch=THREE.MathUtils.clamp(player.pitch,-1.34,1.25)});
canvas.addEventListener('click',()=>{if(player.active&&!player.paused&&!mouseLocked)requestLock()});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','Tab'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'&&player.active){player.paused?resume():pause()}if(!player.active||player.paused)return;if(e.code==='Tab'){e.preventDefault();cycleTarget()}if(e.code==='KeyQ')cycleSpell(-1);if(e.code==='KeyE')cycleSpell(1);if(e.code==='KeyF')castSpecial();if(e.code==='KeyR')recharge();if(e.code==='Space'&&player.ground)player.vel.y=7.1;if(e.code==='ControlLeft'||e.code==='ControlRight')player.crouch=true});
document.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='ControlLeft'||e.code==='ControlRight')player.crouch=false});
$('#againBtn').addEventListener('click',()=>{});
function cycleSpell(d){const arr=getSelected();spellIndex=(spellIndex+d+arr.length)%arr.length;renderSpellHud();sfx(500,.06,'triangle',.022)}
const enemies=[],projectiles=[],effects=[];let waveTimer=0;
const enemyDefs={warrior:{name:'Sanctum Guard',hp:72,speed:2.55,damage:11,range:2.05,rate:1.5,color:0x8c4c48,scale:1,kind:'melee'},archer:{name:'Ashen Archer',hp:55,speed:1.5,damage:9,range:13,rate:2.45,color:0x9c744b,scale:.94,kind:'ranged'},mage:{name:'Rift Adept',hp:64,speed:1.3,damage:12,range:10,rate:2.2,color:0x66539c,scale:1,kind:'ranged'},brute:{name:'Ironbound Brute',hp:190,speed:.95,damage:22,range:2.5,rate:2.1,color:0x596661,scale:1.45,kind:'melee'},assassin:{name:'Gloam Assassin',hp:58,speed:3.6,damage:14,range:1.7,rate:1.18,color:0x7d385a,scale:.89,kind:'melee'},elite:{name:'Warden Elite',hp:145,speed:2.15,damage:17,range:2.15,rate:1.3,color:0xc18a42,scale:1.16,kind:'melee'},boss:{name:'Ancient Colossus',hp:980,speed:.9,damage:26,range:4.7,rate:2.65,color:0x41665e,scale:3.45,kind:'boss'}};
function makeEnemy(type,x,z,extra=1){const d=enemyDefs[type],g=new THREE.Group();g.position.set(x,0,z);const scale=d.scale;
const bodyMat=mat(d.color,.56,.14),dark=mat(type==='boss'?0x172b32:0x312c31,.8,.2),gold=mat(type==='boss'?0xc1a456:0x9d824f,.45,.6),glow=new THREE.MeshBasicMaterial({color:type==='mage'?0x9c77ff:type==='assassin'?0xed4e95:type==='boss'?0x76e1cc:0xf0ad5d});
const body=new THREE.Mesh(new THREE.CapsuleGeometry(.46,.78,5,9),bodyMat);body.position.y=1.08;body.castShadow=true;g.add(body);
const head=new THREE.Mesh(new THREE.SphereGeometry(.37,12,10),dark);head.position.y=1.93;head.scale.set(.9,1.04,.87);head.castShadow=true;g.add(head);
const hood=new THREE.Mesh(new THREE.ConeGeometry(.54,.65,8),bodyMat);hood.position.y=2.19;hood.rotation.x=.12;g.add(hood);
for(let side of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(type==='boss'?.15:.07,8,8),glow);eye.position.set(side*(type==='boss'?.38:.19),type==='boss'?4.45:1.98,.32*scale);g.add(eye)}
const shoulder=new THREE.Mesh(new THREE.BoxGeometry(1.23,.32,.6),dark);shoulder.position.y=1.57;shoulder.castShadow=true;g.add(shoulder);
for(let side of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.55,3,7),bodyMat);arm.position.set(side*.69,1.02,0);arm.rotation.z=side*-.14;g.add(arm);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.17,.43,3,7),dark);leg.position.set(side*.23,.43,0);g.add(leg)}
const armor=new THREE.Mesh(new THREE.BoxGeometry(.77,.72,.24),dark);armor.position.set(0,1.13,.37);g.add(armor);const crest=new THREE.Mesh(new THREE.BoxGeometry(.08,.61,.03),gold);crest.position.set(0,1.15,.51);g.add(crest);
let weapon;if(type==='archer'){weapon=new THREE.Mesh(new THREE.TorusGeometry(.36,.045,5,12,Math.PI),gold);weapon.position.set(.66,1.16,.06);weapon.rotation.z=-Math.PI/2;g.add(weapon)}else if(type==='mage'){weapon=new THREE.Mesh(new THREE.CylinderGeometry(.035,.05,1.1,7),gold);weapon.position.set(.7,1.1,0);weapon.rotation.z=-.12;g.add(weapon);let orb=new THREE.Mesh(new THREE.IcosahedronGeometry(.17),glow);orb.position.set(.69,1.72,.02);g.add(orb)}else{weapon=new THREE.Mesh(new THREE.BoxGeometry(.12,.95,.12),gold);weapon.position.set(.76,1.28,0);weapon.rotation.z=-.25;g.add(weapon);let blade=new THREE.Mesh(new THREE.ConeGeometry(.14,.34,4),dark);blade.position.set(.76,1.9,0);g.add(blade)}
if(type==='boss'){const hornMat=gold;for(let side of [-1,1]){let horn=new THREE.Mesh(new THREE.ConeGeometry(.3,1.2,6),hornMat);horn.position.set(side*1.04,5.08,.06);horn.rotation.z=side*-.47;g.add(horn)}const chest=new THREE.Mesh(new THREE.IcosahedronGeometry(1.12,1),new THREE.MeshStandardMaterial({color:0x1d8f85,emissive:0x0d6258,emissiveIntensity:1.6,metalness:.4,roughness:.27}));chest.position.set(0,3.25,.78);chest.name='weakpoint';g.add(chest);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.45,.07,8,32),gold);ring.position.set(0,3.25,.8);g.add(ring)}
const hp=d.hp*extra;const bar=new THREE.Group();const bg=new THREE.Mesh(new THREE.PlaneGeometry(1.05,.1),new THREE.MeshBasicMaterial({color:0x15151a,side:THREE.DoubleSide}));bar.add(bg);const fg=new THREE.Mesh(new THREE.PlaneGeometry(1,.065),new THREE.MeshBasicMaterial({color:type==='boss'?0x55d7bd:0xd25951,side:THREE.DoubleSide}));fg.position.z=.01;bar.add(fg);bar.position.set(0,type==='boss'?7.4:2.85,0);g.add(bar);
scene.add(g);const e={type,d,group:g,hp,maxHp:hp,bar,fg,attack:Math.random()*.8,phase:0,slow:0,bind:0,alive:true,seed:Math.random()*10,strafe:Math.random()<.5?-1:1,stagger:0,body};enemies.push(e);return e}
const waveDefs=[{title:'WAVE I',sub:'THE OUTER SANCTUM',set:['warrior','warrior','archer']},{title:'WAVE II',sub:'THE WARDENS’ OATH',set:['warrior','archer','mage','assassin']},{title:'WAVE III',sub:'SHADOWS IN THE RIFT',set:['brute','assassin','mage','archer','elite']},{title:'WAVE IV',sub:'THE COLOSSUS AWAKENS',set:['boss','archer','mage']}];
function nextWave(){player.wave++;if(player.wave>waveDefs.length){winGame();return}let w=waveDefs[player.wave-1];$('#waveLabel').textContent=`${['I','II','III','IV'][player.wave-1]} — ${w.sub}`;$('#threatLevel').textContent=['I','II','III','IV'][player.wave-1];$('#objective').textContent=player.wave===4?'DEFEAT THE COLOSSUS':'DEFEAT ALL FOES';$('#bossbar').classList.toggle('hidden',player.wave!==4);const scale=1+(player.wave-1)*.19;w.set.forEach((type,i)=>{const a=(i/w.set.length)*Math.PI*2+Math.random()*.35,r=player.wave===4&&type==='boss'?19:15+Math.random()*4;makeEnemy(type,Math.sin(a)*r, -Math.cos(a)*r,scale)});announce(w.title,w.sub);waveTimer=0;updateHud()}
function winGame(){player.active=false;player.paused=true;document.exitPointerLock?.();$('#victoryScreen').classList.remove('hidden');sfx(660,.6,'sine',.06);setTimeout(()=>sfx(880,.7,'sine',.05),220)}
function updateEnemyBar(e){const ratio=Math.max(0,e.hp/e.maxHp);e.fg.scale.x=ratio;e.fg.position.x=-(1-ratio)*.5;e.bar.quaternion.copy(camera.quaternion)}
function cycleTarget(){const candidates=enemies.filter(e=>e.alive).sort((a,b)=>a.group.position.distanceTo(player.pos)-b.group.position.distanceTo(player.pos));if(!candidates.length){player.locked=null;return}let i=candidates.indexOf(player.locked);player.locked=candidates[(i+1)%candidates.length];sfx(620,.07,'triangle',.025);updateHud()}
function chooseTarget(){const candidates=enemies.filter(e=>e.alive);if(!candidates.length)return null;const dir=new THREE.Vector3(0,0,-1).applyEuler(camera.rotation);let best=null,score=Infinity;for(const e of candidates){const delta=e.group.position.clone().add(new THREE.Vector3(0,e.type==='boss'?3:1.5,0)).sub(camera.position),dist=delta.length();const angle=dir.angleTo(delta.normalize());const val=angle+dist*.002;if(angle<.35&&val<score){score=val;best=e}}return best}
function spellHit(e,spell,scale=1){if(!e||!e.alive)return;let damage=spell.damage*scale;if(e.type==='boss'){let weak=e.group.getObjectByName('weakpoint');damage*=weak&&player.locked===e&&weak.visible?1.38:.76}e.hp-=damage;e.stagger=.13;if(spell.id==='bind'){e.bind=2.7;e.slow=2.7}if(spell.id==='fire'||spell.id==='ruin'){for(const other of enemies){if(other!==e&&other.alive&&other.group.position.distanceTo(e.group.position)<(spell.id==='ruin'?8:4.1)){other.hp-=damage*.45;hitSpark(other.group.position.clone().add(new THREE.Vector3(0,1,0)),0xff8247)}}}if(e.hp<=0){e.alive=false;player.kills++;$('#killCount').textContent=String(player.kills).padStart(2,'0');player.mana=Math.min(100,player.mana+8);player.hp=Math.min(100,player.hp+3);deathFx(e);sfx(105,.22,'sawtooth',.045);if(e.type==='boss')$('#bossbar').classList.add('hidden')}updateEnemyBar(e);hitSpark(e.group.position.clone().add(new THREE.Vector3(0,e.type==='boss'?3:1.5,0)),spell.id==='fire'?0xff844a:spell.id==='void'?0xb29cff:0x73ebd4);$('#hitmarker').classList.remove('hidden');clearTimeout(spellHit.timer);spellHit.timer=setTimeout(()=>$('#hitmarker').classList.add('hidden'),180);sfx(spell.id==='void'?185:470,.1,spell.id==='fire'?'sawtooth':'triangle',.024);updateHud()}
function hitSpark(pos,color){const geo=new THREE.IcosahedronGeometry(.12,0),m=new THREE.MeshBasicMaterial({color,transparent:true});const mesh=new THREE.Mesh(geo,m);mesh.position.copy(pos);scene.add(mesh);effects.push({mesh,life:.42,max:.42,vel:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3),kind:'spark'})}
function deathFx(e){for(let i=0;i<12;i++)hitSpark(e.group.position.clone().add(new THREE.Vector3((Math.random()-.5)*1.5,Math.random()*2,(Math.random()-.5)*1.5)),e.type==='boss'?0x55d7bd:e.d.color);e.group.visible=false;setTimeout(()=>scene.remove(e.group),900)}
function makeProjectile(pos,dir,color,speed,damage,spell,owner='player'){const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(owner==='player'?.17:.2,1),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.95}));mesh.position.copy(pos);scene.add(mesh);let glow=new THREE.PointLight(color,2.4,4,2);mesh.add(glow);projectiles.push({mesh,dir:dir.clone().normalize(),speed,damage,spell,owner,life:owner==='player'?3.2:5,hit:new Set()})}
function fireSpell(){if(!player.active||player.paused||!mouseLocked)return;const spell=getSelected()[spellIndex];if(!spell)return;let now=performance.now()/1000;if(now-(cooldowns[spell.id]||0)<spell.cool)return;if(player.mana<spell.cost){notify('ARCANE RESERVE DEPLETED · PRESS R');sfx(110,.15,'sawtooth',.025);return}player.mana-=spell.cost;cooldowns[spell.id]=now;player.casting=.23;$('#hud').classList.add('casting');setTimeout(()=>$('#hud').classList.remove('casting'),220);const direction=new THREE.Vector3(0,0,-1).applyEuler(camera.rotation),origin=camera.position.clone().add(direction.clone().multiplyScalar(.8)).add(new THREE.Vector3(0,-.12,0));const colors={bolt:0x79f2db,fire:0xff7444,void:0xa98dff,storm:0x69caff,barrage:0x8be4ff,bind:0x94efbb,ruin:0xe6bb61};
if(spell.id==='storm'){let pool=enemies.filter(e=>e.alive&&e.group.position.distanceTo(player.pos)<spell.range).sort((a,b)=>a.group.position.distanceTo(player.pos)-b.group.position.distanceTo(player.pos)).slice(0,4);pool.forEach((e,i)=>{setTimeout(()=>spellHit(e,spell,1-i*.12),i*90);lightningArc(origin,e.group.position.clone().add(new THREE.Vector3(0,1,0)),colors[spell.id])})}
else if(spell.id==='ruin'){for(const e of enemies)if(e.alive&&e.group.position.distanceTo(player.pos)<spell.range)spellHit(e,spell,Math.max(.35,1-e.group.position.distanceTo(player.pos)/38));burst(origin,colors[spell.id]);}
